5	namespace AtrioTeam\DigitalHub\Catalog\Filament\Pages;
6	
7	use AtrioTeam\DigitalHub\Catalog\CatalogHierarchy;
8	use AtrioTeam\DigitalHub\Catalog\Level;
9	use BackedEnum;
10	use Filament\Actions\Concerns\InteractsWithActions;
11	use Filament\Actions\Contracts\HasActions;
12	use Filament\Actions\EditAction;
13	use Filament\Pages\Page;
14	use Filament\Schemas\Schema;
15	use Filament\Support\Enums\Width;
16	use Filament\Support\Icons\Heroicon;
17	use Illuminate\Database\Eloquent\Builder;
18	use Illuminate\Database\Eloquent\Model;
19	use Illuminate\Database\Eloquent\Relations\Relation;
20	use Livewire\WithPagination;
21	use Override;
22	
23	/**
24	 * Page "Catalogo" — navigazione drill-down stile Miller columns.
25	 *
26	 * Lo stato `$path` è una lista ordinata di selezioni (una per livello
27	 * raggiunto). Le colonne renderizzate sono calcolate a partire da `$path`
28	 * percorrendo la gerarchia registrata in `CatalogHierarchy`.
29	 */
30	class Catalog extends Page implements HasActions
31	{
32	    use InteractsWithActions;
33	    use WithPagination;
34	
35	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedSquares2x2;
36	
37	    protected static ?int $navigationSort = 0;
38	
39	    protected string $view = 'digital-hub::filament.pages.catalog';
40	
41	    protected Width | string | null $maxContentWidth = Width::Full;
42	
43	
44	    /**
45	     * Catena di selezioni correnti. Una entry per livello raggiunto.
46	     *
47	     * @var array<int, array{record_id: int|string, active_child: int}>
48	     */
49	    public array $path = [];
50	
51	    #[Override]
52	    public static function getNavigationGroup(): ?string
53	    {
54	        return __('digital-hub::catalog.navigation_label');
55	    }
56	
57	    #[Override]
58	    public static function getNavigationLabel(): string
59	    {
60	        // get resoruce that is the root of the catalog hierarchy, to get the navigation label
61	        $root = app(CatalogHierarchy::class)->root();
62	        $fallback = (string) __('digital-hub::catalog.navigation_label');
63	        if ($root === null) {
64	            return $fallback;
65	        }
66	
67	        $label = $root->resourceClass::getNavigationLabel();
68	
69	        return is_string($label) ? $label : $fallback;
70	    }
71	
72	    #[Override]
73	    public function getTitle(): string|\Illuminate\Contracts\Support\Htmlable
74	    {
75	        return static::getNavigationLabel();
76	    }
77	
78	    public static function shouldRegisterNavigation(): bool
79	    {
80	        return ! app(CatalogHierarchy::class)->isEmpty();
81	    }
82	
83	    /**
84	     * Seleziona un record alla profondità data. Tronca la coda del path
85	     * (le selezioni successive non sono più valide).
86	     */
87	    public function selectRecord(int $depth, int|string $recordId): void
88	    {
89	        $this->path = array_slice($this->path, 0, $depth);
90	        $this->path[] = ['record_id' => $recordId, 'active_child' => 0];
91	    }
92	
93	    /**
94	     * Cambia il tipo di figli mostrato alla profondità data (tab switcher
95	     * quando un livello ammette più sub-entità). Tronca le selezioni
96	     * successive.
97	     */
98	    public function selectChildType(int $depth, int $childIndex): void
99	    {
100	        if (! isset($this->path[$depth])) {
101	            return;
102	        }
103	
104	        $this->path[$depth]['active_child'] = $childIndex;
105	        $this->path = array_slice($this->path, 0, $depth + 1);
106	    }
107	
108	    /**
109	     * Reset alla radice.
110	     */
111	    public function clearPath(): void
112	    {
113	        $this->path = [];
114	    }
115	
116	    /**
117	     * Action parametrica per editare un record di un qualunque livello in modale.
118	     *
119	     * Va invocata nel blade con tre arguments: `model_class`, `resource_class`,
120	     * `record_id`. Esempio:
121	     *
122	     *     ($this->editAction)([
123	     *         'model_class' => $level->modelClass,
124	     *         'resource_class' => $level->resourceClass,
125	     *         'record_id' => $record->getKey(),
126	     *     ])
127	     *
128	     * Il form della modale viene preso dal `Resource::form()` del livello
129	     * stesso, quindi la modale mostra esattamente lo stesso schema del Edit
130	     * Resource — senza duplicazione.
131	     */
132	    public function editAction(): EditAction
133	    {
134	        // Action name must match the method name (without `Action` suffix)
135	        // — Filament resolves `{name}Action()` via convention.
136	        return EditAction::make('edit')
137	            ->iconButton()
138	            ->icon(Heroicon::OutlinedPencilSquare)
139	            ->record(function (array $arguments): ?Model {
140	                /** @var class-string<Model> $modelClass */
141	                $modelClass = $arguments['model_class'];
142	                $record = $modelClass::query()->find($arguments['record_id']);
143	
144	                return $record instanceof Model ? $record : null;
145	            })
146	            // get the schema from the resource class, to avoid duplicating form definitions. The resource class is passed as argument.
147	            ->schema(function (Schema $schema, array $arguments): Schema {
148	                /** @var class-string<\Filament\Resources\Resource> $resourceClass */
149	                $resourceClass = $arguments['resource_class'];
150	
151	                return $resourceClass::form($schema);
152	            })
153	            // singular label tradotto via Resource::getModelLabel(), così la heading è "Modifica Categoria" e non "Modifica Category 1"
154	            ->modelLabel(function (array $arguments): string {
155	                /** @var class-string<\Filament\Resources\Resource> $resourceClass */
156	                $resourceClass = $arguments['resource_class'];
157	
158	                return $resourceClass::getModelLabel();
159	            })
160	            ->slideOver();
161	    }
162	
163	    /**
164	     * Calcola le colonne da renderizzare percorrendo la gerarchia in base a `$path`.
165	     * Utilizza CatalogHierarchy, che detiene le info sulla catena di Level.
166	     *
167	     * @return array<array{
168	     *     depth: int,
169	     *     level: Level,
170	     *     parent_record: ?Model,
171	     *     records: \Illuminate\Contracts\Pagination\Paginator<int,Model>,
172	     *     selected_id: int|string|null,
173	     *     selected_record: ?Model,
174	     *     child_levels: array<Level>,
175	     *     active_child: int,
176	     * }>
177	     */
178	    public function getColumns(): array
179	    {
180	        $hierarchy = app(CatalogHierarchy::class);
181	
182	        if ($hierarchy->isEmpty()) {
183	            return [];
184	        }
185	
186	        $columns = [];
187	        $level = $hierarchy->root();
188	        $parentRecord = null;
189	        $depth = 0;
190	
191	        while ($level !== null) {
192	            $selectedId = $this->path[$depth]['record_id'] ?? null;
193	            $selectedRecord = $selectedId !== null
194	                ? $level->modelClass::query()->find($selectedId)
195	                : null;
196	
197	            $columns[] = [
198	                'depth' => $depth,
199	                'level' => $level,
200	                'parent_record' => $parentRecord,
201	                'records' => $this->queryFor($level, $parentRecord)->paginate(100, pageName: "page_{$depth}"),
202	                'selected_id' => $selectedId,
203	                'selected_record' => $selectedRecord,
204	                'child_levels' => $selectedRecord !== null ? $level->childLevelsFor($selectedRecord) : [],
205	                'active_child' => $this->path[$depth]['active_child'] ?? 0,
206	            ];
207	
208	            if ($selectedRecord === null) {
209	                break;
210	            }
211	
212	            $childLevels = $level->childLevelsFor($selectedRecord);
213	            if ($childLevels === []) {
214	                break;
215	            }
216	
217	            $activeChild = $this->path[$depth]['active_child'] ?? 0;
218	            $level = $childLevels[$activeChild] ?? $childLevels[0];
219	            $parentRecord = $selectedRecord;
220	            $depth++;
221	        }
222	
223	        return $columns;
224	    }
225	
226	
227	    /**
228	     * Builder della query per un determinato livello e record padre. Per
229	     * livelli non-root usa la relazione Eloquent `childrenRelation` sul
230	     * model parent. Applica `withCount(...)` sulle relazioni dei child
231	     * levels statici per evitare N+1 sui badge dei figli.
232	     *
233	     * @return Builder<Model>
234	     */
235	    private function queryFor(Level $level, ?Model $parentRecord): Builder
236	    {
237	        $query = $level->modelClass::query();
238	
239	        if ($parentRecord !== null && $level->childrenRelation !== null) {
240	            $relation = $parentRecord->{$level->childrenRelation}();
241	            if ($relation instanceof Relation) {
242	                /** @var Builder<Model> $query */
243	                $query = $relation->getQuery();
244	            }
245	        }
246	
247	        $countRelations = $this->staticChildCountRelations($level);
248	        if ($countRelations !== []) {
249	            $query->withCount($countRelations);
250	        }
251	
252	        return $query;
253	    }
254	
255	    /**
256	     * Conta i figli diretti di un record. Se i child levels hanno
257	     * `childrenRelation` e la query li ha eager-loaded via `withCount`,
258	     * legge `{relation}_count` dagli attributi del record. Fallback: query
259	     * singola (capita per livelli con `childLevelsFor` dinamico per record).
260	     */
261	    public function childrenCountFor(Level $level, Model $record): int
262	    {
263	        $total = 0;
264	        foreach ($level->childLevelsFor($record) as $childLevel) {
265	            $relation = $childLevel->childrenRelation;
266	            if ($relation === null) {
267	                continue;
268	            }
269	
270	            $attr = $relation . '_count';
271	            if (array_key_exists($attr, $record->getAttributes())) {
272	                $value = $record->getAttribute($attr);
273	                $total += is_numeric($value) ? (int) $value : 0;
274	
275	                continue;
276	            }
277	
278	            // Fallback non eager-loaded (es. childLevelsFor dinamico per record)
279	            $rel = $record->{$relation}();
280	            if ($rel instanceof Relation) {
281	                $total += $rel->count();
282	            }
283	        }
284	
285	        return $total;
286	    }
287	
288	    /**
289	     * Nomi di relazione dei child levels "statici" del livello dato, da
290	     * passare a `withCount(...)`. "Statico" = `childLevelsFor` invocato su
291	     * un'istanza vuota del model del livello ritorna la stessa lista che
292	     * ritornerebbe sui record reali. Per livelli con scoperta dinamica
293	     * (es. Product → sub-entità via `productType`), un'istanza vuota
294	     * tipicamente ritorna `[]` e il count cade naturalmente sul fallback
295	     * non eager.
296	     *
297	     * @return list<string>
298	     */
299	    private function staticChildCountRelations(Level $level): array
300	    {
301	        try {
302	            $sampleRecord = new $level->modelClass();
303	            $childLevels = $level->childLevelsFor($sampleRecord);
304	        } catch (\Throwable) {
305	            return [];
306	        }
307	
308	        $relations = [];
309	        foreach ($childLevels as $childLevel) {
310	            if ($childLevel->childrenRelation !== null) {
311	                $relations[] = $childLevel->childrenRelation;
312	            }
313	        }
314	
315	        return $relations;
316	    }
317	}
