2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Assets\Filament\Pages;
6	
7	use AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets;
8	use AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob;
9	use AtrioTeam\DigitalHub\Assets\Metadata\ExtractedMetadata;
10	use AtrioTeam\DigitalHub\Assets\Models\AssetFolder;
11	use AtrioTeam\DigitalHub\Assets\Models\AssetShare;
12	use AtrioTeam\DigitalHub\Assets\Support\AssetPreview;
13	use AtrioTeam\DigitalHub\Assets\Support\AssetProcessingStatus;
14	use AtrioTeam\DigitalHub\Assets\Support\AssetSummary;
15	use AtrioTeam\DigitalHub\Assets\Support\AssetUrl;
16	use BackedEnum;
17	use Filament\Actions\Action;
18	use Filament\Actions\Concerns\InteractsWithActions;
19	use Filament\Actions\Contracts\HasActions;
20	use Filament\Forms\Components\DatePicker;
21	use Filament\Forms\Components\FileUpload;
22	use Filament\Forms\Components\Select;
23	use Filament\Forms\Components\TextInput;
24	use Filament\Infolists\Components\Entry;
25	use Filament\Infolists\Components\KeyValueEntry;
26	use Filament\Infolists\Components\TextEntry;
27	use Filament\Infolists\Components\ViewEntry;
28	use Filament\Notifications\Notification;
29	use Filament\Pages\Page;
30	use Filament\Panel;
31	use Filament\Schemas\Components\Fieldset;
32	use Filament\Schemas\Components\Section;
33	use Filament\Schemas\Components\Tabs;
34	use Filament\Schemas\Components\Tabs\Tab;
35	use Filament\Schemas\Schema;
36	use Filament\Support\Enums\Width;
37	use Filament\Support\Icons\Heroicon;
38	use Illuminate\Contracts\Support\Htmlable;
39	use Illuminate\Database\Eloquent\Collection as EloquentCollection;
40	use Illuminate\Database\Eloquent\Model;
41	use Illuminate\Database\Eloquent\Relations\Relation;
42	use Illuminate\Support\Facades\Storage;
43	use Illuminate\Validation\ValidationException;
44	use Livewire\Features\SupportFileUploads\TemporaryUploadedFile;
45	use Override;
46	use Spatie\MediaLibrary\MediaCollections\Models\Media;
47	use Symfony\Component\HttpFoundation\StreamedResponse;
48	
49	/**
50	 * Gestione asset di un singolo record (digital-hub #16).
51	 *
52	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
53	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
54	 * nella tabella di una resource. La route porta owner via coppia polimorfica
55	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
56	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
57	 *
58	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
59	 * di #16a; qui c'è solo lo scheletro navigabile.
60	 */
61	class AssetManager extends Page implements HasActions
62	{
63	    use InteractsWithActions;
64	
65	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
66	
67	    protected static ?string $slug = 'assets';
68	
69	    protected string $view = 'digital-hub::filament.pages.asset-manager';
70	
71	    protected Width|string|null $maxContentWidth = Width::Full;
72	
73	    /** icona di "sposta", usata per file e cartelle */
74	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
75	
76	    /** Morph alias del record proprietario (es. `product`). */
77	    public string $ownerType;
78	
79	    /** Chiave primaria del record proprietario. */
80	    public int|string $ownerKey;
81	
82	    /** Folder attualmente selezionata; null = root (tutti gli asset del record). */
83	    public ?int $activeFolderId = null;
84	
85	    /**
86	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
87	     * per il link "indietro". null se assente o non locale. È public così
88	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
89	     */
90	    public ?string $returnUrl = null;
91	
92	    /**
93	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
94	     * @var array<int, int|string>
95	     */
96	    public array $selectedAssetIds = [];
97	
98	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
99	    public ?string $lastShareUrl = null;
100	
101	    /**
102	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
103	     * @var (Model&OwnsAssets)|null
104	     */
105	    private ?Model $ownerModel = null;
106	
107	    /**
108	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
109	     * @var null|EloquentCollection<int,AssetFolder>
110	     */
111	    private ?EloquentCollection $folderCache = null;
112	
113	    #[Override]
114	    public static function getRoutePath(Panel $panel): string
115	    {
116	        return '/assets/{ownerType}/{owner}';
117	    }
118	
119	    public static function shouldRegisterNavigation(): bool
120	    {
121	        return false;
122	    }
123	
124	    /**
125	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
126	     */
127	    public function mount(string $ownerType, int|string $owner): void
128	    {
129	        $this->ownerType = $ownerType;
130	        $this->ownerKey = $owner;
131	
132	        // valida subito: record risolvibile e dotato del trait HasAssets
133	        $this->resolveOwner();
134	
135	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
136	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
137	        // Fallback (link diretto/tab nuova, niente referer): la lista della
138	        // resource del record, senza filtri.
139	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
140	            ?? $this->resourceIndexUrl();
141	    }
142	
143	    /**
144	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
145	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
146	     * pagina asset stessa (es. reload). null se non valido.
147	     */
148	    private function resolveReturnUrl(?string $url): ?string
149	    {
150	        if (! is_string($url) || $url === '') {
151	            return null;
152	        }
153	
154	        $host = parse_url($url, PHP_URL_HOST);
155	        if ($host !== null && $host !== request()->getHost()) {
156	            return null;
157	        }
158	
159	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
160	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
161	            return null;
162	        }
163	
164	        return $url;
165	    }
166	
167	    /**
168	     * URL della lista (index) della resource Filament del record, da usare come
169	     * fallback quando manca un Referer valido. null se il record non ha una
170	     * resource registrata nel pannello o l'URL non è risolvibile.
171	     */
172	    private function resourceIndexUrl(): ?string
173	    {
174	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
175	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
