371	    /**
372	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
373	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
374	     *
375	     * @return list<AssetFolder>
376	     */
377	    public function getBreadcrumbTrail(): array
378	    {
379	        if ($this->activeFolderId === null) {
380	            return [];
381	        }
382	
383	        $folders = $this->allFolders();
384	        $trail = [];
385	        $id = $this->activeFolderId;
386	
387	        while ($id !== null) {
388	            $folder = $folders->firstWhere('id', $id);
389	            if (! $folder instanceof AssetFolder) {
390	                // folder eliminata sotto i piedi: torna a root
391	                $this->activeFolderId = null;
392	
393	                return [];
394	            }
395	
396	            array_unshift($trail, $folder);
397	            $id = $folder->parent_id;
398	        }
399	
400	        return $trail;
401	    }
