421	    /**
422	     * Percorso completo (root → cartella) del media, per il badge nella vista
423	     * aggregata "Tutti gli asset". Es. "Documenti / 2024".
424	     * null = media non assegnato a nessuna folder.
425	     */
426	    public function assetFolderPath(Media $media): ?string
427	    {
428	        $id = $media->getAttribute('asset_folder_id');
429	        if (! is_numeric($id)) {
430	            return null;
431	        }
432	
433	        $folders = $this->allFolders();
434	        $names = [];
435	        $current = (int) $id;
436	        $guard = 0;
437	
438	        while ($current !== null) {
439	            $folder = $folders->firstWhere('id', $current);
440	            if (! $folder instanceof AssetFolder) {
441	                break;
442	            }
443	
444	            array_unshift($names, $folder->name);
445	            $current = $folder->parent_id;
446	
447	            if (++$guard > AssetFolder::MAX_DEPTH + 1) {
448	                break; // safety contro catene anomale
449	            }
450	        }
451	
452	        return $names === [] ? null : implode(' / ', $names);
453	    }
