641	    /**
642	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
643	     * I file finiscono nella collection asset del record (disco scoped).
644	     */
645	    public function uploadAssetsAction(): Action
646	    {
647	        return Action::make('uploadAssets')
648	            ->label(__('digital-hub::assets.upload'))
649	            ->icon(Heroicon::OutlinedArrowUpTray)
650	            ->modalHeading(__('digital-hub::assets.upload_heading'))
651	            ->schema([
652	                FileUpload::make('files')
653	                    ->label(__('digital-hub::assets.files_field'))
654	                    ->multiple()
655	                    ->required()
656	                    ->storeFiles(false),
657	            ])
658	            ->action(function (array $data): void {
659	                $owner = $this->resolveOwner();
660	                $files = $data['files'] ?? [];
661	                if (! is_array($files)) {
662	                    return;
663	                }
664	
665	                $count = 0;
666	                foreach ($files as $file) {
667	                    if (! $file instanceof TemporaryUploadedFile) {
668	                        continue;
669	                    }
670	
671	                    $media = $owner->addMedia($file)
672	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
673	                        ->toMediaCollection($owner->assetsCollection());
674	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
675	
676	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
677	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
678	                    /** @disregard P1013 */
679	                    $user = auth()->user();
680	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
681	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
682	
683	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
684	                    // job in coda: il media entra "pending" finché il job non lo chiude
685	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
686	                    $media->save();
687	
688	                    $this->dispatchProcessing($media);
689	                    $count++;
690	                }
691	
692	                if ($count > 0) {
693	                    Notification::make()
694	                        ->success()
695	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
696	                        ->send();
697	                }
698	            });
699	    }
