808	     * annidati (sezioni EXIF, liste IPTC) sono appiattiti in dot-notation perché
809	     * il KeyValueEntry rende solo coppie chiave→scalare. Vuoto se non ci sono
810	     * metadati (media non ancora processato).
811	     *
812	     * @return list<Section>
813	     */
814	    private function assetMetadataSections(Media $media): array
815	    {
816	        $metadata = ExtractedMetadata::forMedia($media);
817	
818	        $labels = [
819	            'common' => __('digital-hub::assets.meta_block_common'),
820	            'exif' => 'EXIF',
821	            'iptc' => 'IPTC',
822	            'xmp' => 'XMP',
823	        ];
824	
825	        $sections = [];
826	        foreach ($labels as $key => $label) {
827	            $block = $metadata[$key] ?? null;
828	            if (! is_array($block)) {
829	                continue;
830	            }
831	
832	            $flat = ExtractedMetadata::flatten($block);
833	            if ($flat === []) {
834	                continue;
835	            }
836	
837	            $sections[] = Section::make($label)
838	                ->heading('')
839	                // ->collapsible()
840	                // ->collapsed($key !== 'common') // i generali aperti, i blocchi grezzi chiusi
841	                ->schema([
842	                    Fieldset::make($label)
843	                        ->columnSpanFull()
844	                        ->columns(1)
845	                        ->contained(false)
846	                        ->schema([
847	                            KeyValueEntry::make("meta_{$key}")
848	                                ->hiddenLabel()
849	                                ->state($flat)
850	                                ->keyLabel(__('digital-hub::assets.meta_key'))
851	                                ->valueLabel(__('digital-hub::assets.meta_value')),
852	                        ]),
853	                ]);
854	        }
855	
856	        return $sections;
857	    }
