1144	     * Se $excludeId è dato, salta quella folder e tutto il suo sottoalbero
1145	     * (serve allo spostamento di cartelle: una folder non può finire dentro sé
1146	     * stessa o un proprio discendente).
1147	     *
1148	     * @return array<int, string>
1149	     */
1150	    public function folderSelectOptions(?int $excludeId = null): array
1151	    {
1152	        $options = [];
1153	        $this->appendFolderOptions(null, 0, $options, $excludeId);
1154	
1155	        return $options;
1156	    }
