1158	    /**
1159	     * @param array<int, string> $options
1160	     */
1161	    private function appendFolderOptions(?int $parentId, int $depth, array &$options, ?int $excludeId = null): void
1162	    {
1163	        foreach ($this->allFolders()->where('parent_id', $parentId) as $folder) {
1164	            if ($excludeId !== null && $folder->id === $excludeId) {
1165	                continue; // salta la folder e (non ricorrendo) il suo sottoalbero
1166	            }
1167	
1168	            $options[$folder->id] = str_repeat('— ', $depth) . $folder->name;
1169	            $this->appendFolderOptions($folder->id, $depth + 1, $options, $excludeId);
1170	        }
1171	    }
1172	
1173	    /**
1174	     * Altezza del sottoalbero di una folder (0 se non ha figli): numero di
1175	     * livelli sotto di essa. Serve a validare la profondità risultante quando
1176	     * si sposta una folder con discendenti.
1177	     */
1178	    private function subtreeHeight(int $folderId): int
1179	    {
1180	        $max = 0;
1181	        foreach ($this->allFolders()->where('parent_id', $folderId) as $child) {
1182	            $max = max($max, 1 + $this->subtreeHeight($child->id));
1183	        }
1184	
1185	        return $max;
1186	    }
1187	
1188	    /**
1189	     * Trova un media verificando che appartenga al record (collection asset).
1190	     * Accetta id mixed (argomento d'azione).
1191	     */
1192	    private function findOwnedMedia(mixed $id): ?Media
1193	    {
1194	        if (! is_numeric($id)) {
1195	            return null;
1196	        }
1197	
1198	        $owner = $this->resolveOwner();
1199	        $media = $owner->media()
1200	            ->where('collection_name', $owner->assetsCollection())
1201	            ->whereKey((int) $id)
1202	            ->first();
1203	
1204	        return $media instanceof Media ? $media : null;
1205	    }
1206	
1207	    /**
1208	     * Trova una folder verificando che appartenga al record. Accetta id mixed
1209	     * (argomento d'azione) e ritorna null se non numerico o non del record.
1210	     */
1211	    private function findOwnedFolder(mixed $id): ?AssetFolder
1212	    {
1213	        if (! is_numeric($id)) {
1214	            return null;
1215	        }
1216	
1217	        $owner = $this->resolveOwner();
1218	
1219	        return AssetFolder::query()
1220	            ->where('folderable_type', $owner->getMorphClass())
1221	            ->where('folderable_id', $owner->getKey())
1222	            ->whereKey((int) $id)
1223	            ->first();
1224	    }
1225	
1226	    /**
1227	     * Salva una folder intercettando le ValidationException del model (profondità,
1228	     * owner, ciclo) e mostrandole come notifica. Invalida la cache delle folder.
1229	     */
1230	    private function persistFolder(AssetFolder $folder): bool
1231	    {
1232	        try {
1233	            $folder->save();
1234	        } catch (ValidationException $e) {
1235	            Notification::make()->danger()->title($this->firstValidationMessage($e))->send();
1236	
1237	            return false;
1238	        }
1239	
1240	        $this->folderCache = null;
1241	
1242	        return true;
1243	    }
1244	
1245	    private function firstValidationMessage(ValidationException $e): string
1246	    {
1247	        $first = collect($e->errors())->flatten()->first();
1248	
1249	        return is_string($first) ? $first : (string) __('digital-hub::asset_folders.cannot_delete_non_empty');
1250	    }
1251	}
