3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Catalog;
6	
7	use Closure;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Support\Str;
10	
11	/**
12	 * Descrive un livello della gerarchia del catalogo.
13	 *
14	 * Il livello è agnostico rispetto al dominio: il template del cliente
15	 * istanzia un Level per ogni modello che vuole far comparire nel drill-down
16	 * (Category1, Category2, Product, ed eventualmente sub-entità Module/Variant
17	 * che entrano in gioco solo via `childLevelsFor`).
18	 */
19	final class Level
20	{
21	    /**
22	     * @param class-string<Model> $modelClass FQN del modello Eloquent del livello.
23	     * @param class-string $resourceClass FQN della Filament Resource (per il link "Apri").
24	     * @param Closure $childLevelsFor `fn(Model $record): list<Level>` — livelli figli applicabili a un record concreto di questo livello. Lista ordinata: per N > 1 la UI mostra un tab switcher.
25	     * @param ?string $childrenRelation Nome della relazione sul model del livello PARENT che restituisce i record di QUESTO livello (es. su `Category2Level`: `'subcategories'`, perché `Category1` ha `->subcategories()`). Null per il livello root. Permette al core di applicare `withCount(...)` eager-loading evitando N+1.
26	     * @param ?Closure $cardLabel `fn(Model $record): string` — override del label della card (default: `$record->name`).
27	     * @param ?Closure $cardSubtitle `fn(Model $record): ?string` — subtitle opzionale mostrato sotto al label.
28	     */
29	    public function __construct(
30	        public readonly string $modelClass,
31	        public readonly string $resourceClass,
32	        public readonly Closure $childLevelsFor,
33	        public readonly ?string $childrenRelation = null,
34	        public readonly ?Closure $cardLabel = null,
35	        public readonly ?Closure $cardSubtitle = null,
36	    ) {
37	    }
38	
39	    /**
40	     * Ritorna i livelli figli per un dato record di questo livello, utilizzando la closure `childLevelsFor` definita in fase di istanziazione.
41	     * @return array<int,Level>
42	     */
43	    public function childLevelsFor(Model $record): array
44	    {
45	        // @phpstan-ignore return.type
46	        return ($this->childLevelsFor)($record);
47	    }
48	
49	    public function labelFor(Model $record): string
50	    {
51	        if ($this->cardLabel !== null) {
52	            // @phpstan-ignore return.type
53	            return ($this->cardLabel)($record);
54	        }
55	
56	        // @phpstan-ignore cast.string
57	        return (string) ($record->getAttribute('name') ?? $record->getKey());
58	    }
59	
60	    public function subtitleFor(Model $record): ?string
61	    {
62	        // @phpstan-ignore return.type
63	        return $this->cardSubtitle !== null ? ($this->cardSubtitle)($record) : null;
64	    }
65	
66	    /**
67	     * Label del livello come collezione (es. "Categorie", "Prodotti").
68	     * Convention: si pesca da `{model_snake}.model_plural` del file lang.
69	     */
70	    public function pluralLabel(): string
71	    {
72	        $key = $this->translationKey();
73	
74	        return __($key . '.model_plural');
75	    }
76	
77	    public function singularLabel(): string
78	    {
79	        $key = $this->translationKey();
80	
81	        return __($key . '.model');
82	    }
83	
84	    private function translationKey(): string
85	    {
86	        $basename = class_basename($this->modelClass);
87	
88	        return Str::snake($basename);
89	    }
90	}
